"""Parse bom.csv (as generated by the build prompt) into per-instance parts."""

from __future__ import annotations

import csv
import re
from dataclasses import dataclass
from pathlib import Path


@dataclass
class BomLine:
    refdes: str
    qty: str
    description: str
    manufacturer: str
    mpn: str
    package: str
    notes: str


@dataclass
class PartInstance:
    refdes: str
    line: BomLine


_RANGE_RE = re.compile(r"^([A-Za-z]+)(\d+)-(?:[A-Za-z]+)?(\d+)$")
_SINGLE_RE = re.compile(r"^([A-Za-z]+)(\d+)$")


def expand_refdes(field: str) -> list[str]:
    """Expand a RefDes cell like "R1, R2, R3" or "R1-R3" into individual refdes."""
    out: list[str] = []
    for token in re.split(r"[,\s]+", field.strip()):
        if not token:
            continue
        m = _RANGE_RE.match(token)
        if m:
            prefix, lo, hi = m.group(1), int(m.group(2)), int(m.group(3))
            out.extend(f"{prefix}{i}" for i in range(lo, hi + 1))
            continue
        out.append(token)
    return out


def _get(row: dict, *names: str) -> str:
    for n in names:
        for k in row:
            if k.strip().lower() == n:
                return (row[k] or "").strip()
    return ""


def load_bom(bom_path: Path) -> list[PartInstance]:
    instances: list[PartInstance] = []
    with bom_path.open(newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            refdes_field = _get(row, "refdes", "ref des", "reference", "designator")
            if not refdes_field:
                continue
            line = BomLine(
                refdes=refdes_field,
                qty=_get(row, "qty", "quantity"),
                description=_get(row, "description", "desc"),
                manufacturer=_get(row, "manufacturer", "mfr"),
                mpn=_get(row, "mpn", "part number", "manufacturer part number"),
                package=_get(row, "package", "footprint"),
                notes=_get(row, "notes", "note"),
            )
            for refdes in expand_refdes(refdes_field):
                instances.append(PartInstance(refdes=refdes, line=line))
    return instances
